    """TIER_ONE: real vina binary + real receptor PDBQT -> float affinity.

    Uses the repo's OWN env-configured path (``vina_objective`` /
    ``VinaAdapter(_config_from_env())``): the verification image exports
    ``VINA_BINARY`` / ``VINA_RECEPTOR_PDBQT`` / ``VINA_BOX``, so this runs the
    exact code a real deployment runs.  The gate verifies:
      * adapter.available() is True (binary + receptor both present)
      * dock(Candidate with pdbqt_text) -> float (kcal/mol, Vina's native sign)
      * evaluator resolve: stamp "real", tier TIER_ONE
      * a PDBQT-less candidate degrades to None WITHOUT raising
    """
    import opensciencelab.docking as dk
    if not receptor_pdbqt:
        receptor_pdbqt = os.environ.get("VINA_RECEPTOR_PDBQT", "")
    if not receptor_pdbqt or not os.path.exists(receptor_pdbqt):
        return {"ok": False, "skip_reason": "no receptor PDBQT (not an adapter "
                                            "failure -- G2 cannot run without one)"}
    cfg = dk._config_from_env()
    if cfg is None or cfg.receptor_pdbqt != receptor_pdbqt:
        cfg = (VinaConfig(receptor_pdbqt=receptor_pdbqt) if cfg is None
               else cfg)
        cfg.receptor_pdbqt = receptor_pdbqt
        if not os.path.exists(receptor_pdbqt):
            return {"ok": False, "reason": "receptor PDBQT missing"}
    adapter = VinaAdapter(cfg)
    if not adapter.available():
        return {"ok": False, "skip_reason": f"VinaAdapter.available() False -- "
                                            f"binary={adapter.config.binary!r} "
                                            "or receptor missing (G2 cannot run)"}
    # Real path: a candidate WITH a PDBQT (the seam the adapter expects).
    pdbqt = descriptors.smiles_to_pdbqt(cand.smi)
    if not pdbqt:
        return {"ok": False, "reason": "pdbqt_text missing -- no dockable input"}
    cand2 = Candidate(id=cand.id, kind=cand.kind, smi=cand.smi,
                      metadata={**dict(cand.metadata or {}), "pdbqt_text": pdbqt})
    aff = adapter.dock(cand2)
    if not isinstance(aff, float) or not _finite(aff):
        return {"ok": False, "reason": f"dock returned {aff!r} (want float)"}
    # The evaluator's resolve(): stamp + tier from ONE resolution.
    ev = make_drug_evaluator(docking_fn=lambda c: adapter.dock(c))
